INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_fehu', 'ᚠ', 'Fehu', 'ELDER', 1, 'Cattle / Wealth', 'GOLD_PERCENT', 5, 'Золото +5%', 'Wealth is source of discord among kin and fire of the sea and path of the serpent.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_uruz', 'ᚢ', 'Uruz', 'ELDER', 1, 'Aurochs', 'CLICK_DAMAGE', 5, 'Урон клика +5%', 'Rain is lamentation of the clouds and destroyer of the hay-harvest.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_thurisaz', 'ᚦ', 'Thurisaz', 'ELDER', 1, 'Giant / Thorn', 'BOSS_DAMAGE', 5, 'Урон по боссам +5%', 'Giant is torture of women and cliff-dweller and husband of a giantess.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_ansuz', 'ᚨ', 'Ansuz', 'ELDER', 1, 'God / Mouth', 'SKILL_POWER', 5, 'Сила умений +5%', 'God is the aged Gautr and prince of Asgard and lord of Valhalla.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_raidho', 'ᚱ', 'Raidho', 'ELDER', 1, 'Riding / Wagon', 'ATTACK_SPEED', 5, 'Скорость атаки +5%', 'Riding is a joy for the sitter and a swift journey and labor for the horse.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_kenaz', 'ᚲ', 'Kenaz', 'ELDER', 1, 'Torch / Ulcer', 'CRIT_CHANCE', 5, 'Шанс крита +5%', 'The torch is known to every living man by its pale, bright flame.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_gebo', 'ᚷ', 'Gebo', 'ELDER', 1, 'Gift', 'DROP_RATE', 5, 'Шанс дропа осколков +5%', 'Generosity is a decoration and praise to all men.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_wunjo', 'ᚹ', 'Wunjo', 'ELDER', 1, 'Joy', 'TEAM_DPS', 5, 'DPS команды +5%', 'He enjoys joy who knows few troubles, pains, or sorrows.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_hagalaz', 'ᚼ', 'Hagalaz', 'ELDER', 2, 'Hail', 'AOE_DAMAGE', 10, 'Урон по всем защитникам +10%', 'Hail is the whitest of grain; it is whirled from heaven.');
INSERT INTO runes (rune_key, symbol, name, futhark, tier, meaning, effect_type, effect_value, effect_description, flavor_text) VALUES ('rune_elder_nauthiz', 'ᚾ', 'Nauthiz', 'ELDER', 2, 'Need', 'SURVIVAL', 10, 'Герой переживает смертельный удар (кд 10 сек)', 'Trouble is oppressive to the heart; yet it often becomes a help.');
